{
  "justification": "With the economy dominating salience and a mid-point tax–spending preference, proportionality (performance/merit) slightly outweighs equality concerns. High salience of immigration and net disapproval of EU membership elevate loyalty (national cohesion) and, with crime/terrorism concerns, a modest authority emphasis, while explicitly moral/religious items are marginal, keeping sanctity low.",
  "foundations": [
    {
      "foundation": "proportionality",
      "basis": "Economy General 46.8% salience; Welfare Fraud 0.9%; midpoint tax–spending preference (5.05/10).",
      "weight": 0.30
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration 18.6% salience and net EU membership disapproval (50.1%), plus National Identity/goals-loss 0.2% and National Security 0.2%.",
      "weight": 0.22
    },
    {
      "foundation": "equality",
      "basis": "Unemployment 3.7%, NHS 1.1%, Education 0.8%, Pensions 0.6%, Class Difference 0.6%, and other social spending 0.7%.",
      "weight": 0.18
    },
    {
      "foundation": "authority",
      "basis": "Crime 6.3% and Terrorism 1.5%, with Government Reform 0.3%, I.D. Cards 0.1%, and Strikes 0.2%.",
      "weight": 0.14
    },
    {
      "foundation": "care",
      "basis": "NHS 1.1%, Environment 1.5%, Youth 0.7%, and Aging Population 0.4% indicate concern for others’ welfare.",
      "weight": 0.10
    },
    {
      "foundation": "sanctity",
      "basis": "Low salience of Family Values—lack 0.4%, Drugs 0.5%, Morals 0.3%, and Failure of Religious 0.1%.",
      "weight": 0.06
    }
  ]
}

{
  "justification": "Because the survey records unprompted salience without direction, I weight foundations by how many and how prominent the named issues plausibly invoke each foundation, not by any specific policy stance. The dominance of economy-related mentions boosts proportionality, while healthcare and the social safety net elevate care; crime/immigration/defence raise authority and loyalty; morality/drugs/environment support sanctity; inequality/low pay/housing add a smaller but clear equality component.",
  "foundations": [
    {"foundation": "proportionality", "basis": "Economy/Economic situation; Inflation/Prices; Taxation; Petrol prices/Fuel; Privatisation; Pound/Exchange rate/Value of Pound; Unemployment/Factory closure/Lack of industry; Education/Schools (merit/investment)", "weight": 0.29},
    {"foundation": "care", "basis": "NHS/Hospitals/Healthcare; Pensions/Social security; Poverty/Inequality; Housing; Drug abuse; Education/Schools (welfare of children); Pollution/Environment", "weight": 0.24},
    {"foundation": "authority", "basis": "Crime/Law and order/Violence/Vandalism; Defence/Foreign affairs/International terrorism; Morality/Individual behaviour; Local government/Council tax/Poll tax; Transport/Public transport (rules/order)", "weight": 0.19},
    {"foundation": "loyalty", "basis": "Race relations/Immigration/Immigrants; Defence/Foreign affairs/International terrorism; Common Market/EU/Europe/Single European Currency; Nuclear weapons/Disarmament; Countryside/Rural life (community identity)", "weight": 0.10},
    {"foundation": "equality", "basis": "Poverty/Inequality; Low pay/Minimum wage/Fair wages; Housing; Education/Schools (opportunity); Unemployment/Factory closure/Lack of industry", "weight": 0.10},
    {"foundation": "sanctity", "basis": "Morality/Individual behaviour; Drug abuse; Pollution/Environment; NHS/Hospitals/Healthcare (purity/contamination concerns)", "weight": 0.08}
  ]
}

{
  "justification": "This salience-only measure lets us gauge orientation by the prominence of identity/order versus green/libertarian value themes, not by positions within policy domains. Immigration, crime/law-and-order, morality, and security are highly salient while environment/disarmament are marginal, so the profile leans TAN.",
  "poles": [
    {"pole": "gal",
     "basis": "Pollution/Environment (5%); Nuclear weapons/Disarmament (1%)",
     "weight": 0.15},
    {"pole": "tan",
     "basis": "Race relations/Immigration/Immigrants (29%); Crime/Law and order/Violence/Vandalism (25%); Morality/Individual behaviour (8%); Drug abuse (7%); Defence/Foreign affairs/International terrorism (11%)",
     "weight": 0.85}
  ]
}

{
  "justification": "EU membership attitudes lean toward disapproval (50.1% vs 31.8% approval), indicating a sovereignty-oriented TAN tilt. Issue salience prioritises immigration and crime over environment or civil liberties, though a notable pro-EU minority and some GAL-coded concerns remain.",
  "poles": [
    {
      "pole": "tan",
      "basis": "Slot 7 majority disapprove of EU membership; Slot 3 immigration and crime salient while environment/civil liberties low.",
      "weight": 0.62
    },
    {
      "pole": "gal",
      "basis": "Slot 7 sizable minority approve EU membership; Slot 3 some attention to environment and civil liberties.",
      "weight": 0.38
    }
  ]
}
